const markPDFSigningAdmissionReadyV1 = `-- name: MarkPDFSigningAdmissionReadyV1 :one
WITH parent AS MATERIALIZED (
 SELECT d.id,d.org_id FROM documents d WHERE d.id=$4 AND d.org_id=$5
 AND current_setting('transaction_isolation')='read committed' FOR UPDATE OF d
), participant_locks AS MATERIALIZED (
 SELECT r.id FROM recipients r JOIN parent d ON d.id=r.document_id ORDER BY r.id FOR UPDATE OF r
), participant_guard AS MATERIALIZED (SELECT count(*) AS n FROM participant_locks)
UPDATE document_signing_admissions a SET status='ready',source_inspection_sha256=$1,ready_at=clock_timestamp(),updated_at=clock_timestamp()
FROM parent d CROSS JOIN participant_guard g WHERE a.id=$2 AND a.org_id=d.org_id AND a.document_id=d.id
 AND a.owner_id=$3 AND a.lease_until>clock_timestamp() AND a.status='staging' AND g.n BETWEEN 1 AND 100
RETURNING a.id,a.org_id,a.document_id,a.static_basis_sha256,a.status,a.ready_at
`

type MarkPDFSigningAdmissionReadyV1Params struct {
	SourceInspectionSha256 []byte    `json:"source_inspection_sha256"`
	AdmissionID            uuid.UUID `json:"admission_id"`
	OwnerID                uuid.UUID `json:"owner_id"`
	DocumentID             uuid.UUID `json:"document_id"`
	OrgID                  uuid.UUID `json:"org_id"`
}

type MarkPDFSigningAdmissionReadyV1Row struct {
	ID                uuid.UUID          `json:"id"`
	OrgID             uuid.UUID          `json:"org_id"`
	DocumentID        uuid.UUID          `json:"document_id"`
	StaticBasisSha256 []byte             `json:"static_basis_sha256"`
	Status            string             `json:"status"`
	ReadyAt           pgtype.Timestamptz `json:"ready_at"`
}

func (q *Queries) MarkPDFSigningAdmissionReadyV1(ctx context.Context, arg MarkPDFSigningAdmissionReadyV1Params) (*MarkPDFSigningAdmissionReadyV1Row, error) {
	row := q.db.QueryRow(ctx, markPDFSigningAdmissionReadyV1,
		arg.SourceInspectionSha256,
		arg.AdmissionID,
		arg.OwnerID,
		arg.DocumentID,
		arg.OrgID,
	)
	var i MarkPDFSigningAdmissionReadyV1Row
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.DocumentID,
		&i.StaticBasisSha256,
		&i.Status,
		&i.ReadyAt,
	)
	return &i, err
}

