const sealAndBindPDFSigningAdmissionV1 = `-- name: SealAndBindPDFSigningAdmissionV1 :one
WITH parent AS MATERIALIZED (
 SELECT d.id,d.org_id FROM documents d WHERE d.id=$7 AND d.org_id=$8
 AND current_setting('transaction_isolation')='read committed' FOR UPDATE OF d
), recipient_lock AS MATERIALIZED (
 SELECT r.id FROM recipients r JOIN parent d ON d.id=r.document_id WHERE r.id=$2 FOR UPDATE OF r
), admission_lock AS MATERIALIZED (
 SELECT a.id,a.status FROM document_signing_admissions a JOIN parent d ON d.id=a.document_id AND d.org_id=a.org_id
 JOIN recipient_lock r ON TRUE WHERE a.id=$9 AND a.static_basis_sha256=$4
 AND ((a.status='ready' AND a.owner_id=$10 AND a.lease_until>clock_timestamp()) OR a.status='sealed') FOR UPDATE OF a
), sealed AS (
 UPDATE document_signing_admissions a SET status='sealed',first_signature_id=$1,sealed_at=clock_timestamp(),updated_at=clock_timestamp()
 FROM admission_lock l WHERE a.id=l.id AND l.status='ready' RETURNING a.id
), chosen AS MATERIALIZED (
 SELECT id FROM sealed UNION ALL SELECT id FROM admission_lock WHERE status='sealed'
), document_seal AS (
 UPDATE documents d SET signing_admission_sealed_id=c.id FROM chosen c WHERE d.id=$7 AND d.org_id=$8
  AND d.signing_admission_active_id=c.id AND (d.signing_admission_sealed_id IS NULL OR d.signing_admission_sealed_id=c.id) RETURNING d.id,d.org_id,c.id AS admission_id
)
INSERT INTO signature_signing_admission_bindings(signature_id,admission_id,org_id,document_id,recipient_id,field_id,static_basis_sha256,reviewed_basis_sha256,selection_id,signed_event_id)
SELECT $1,d.admission_id,d.org_id,d.id,$2,$3,$4,$4,$5,$6
FROM document_seal d RETURNING signature_id,admission_id,org_id,document_id,recipient_id,field_id,static_basis_sha256,selection_id,signed_event_id,bound_at
`

type SealAndBindPDFSigningAdmissionV1Params struct {
	SignatureID         uuid.UUID `json:"signature_id"`
	RecipientID         uuid.UUID `json:"recipient_id"`
	FieldID             uuid.UUID `json:"field_id"`
	ReviewedBasisSha256 []byte    `json:"reviewed_basis_sha256"`
	SelectionID         uuid.UUID `json:"selection_id"`
	SignedEventID       uuid.UUID `json:"signed_event_id"`
	DocumentID          uuid.UUID `json:"document_id"`
	OrgID               uuid.UUID `json:"org_id"`
	AdmissionID         uuid.UUID `json:"admission_id"`
	AdmissionOwnerID    uuid.UUID `json:"admission_owner_id"`
}

